// Some portions generated by Claude
/**
 * Stress layout of rectangular cards by stochastic gradient descent.
 *
 * Stress is Σ w·(distance − target)² over pairs of cards. Zheng, Pawar and Goodman ("Graph Drawing by Stochastic
 * Gradient Descent", IEEE TVCG 2019) minimise it by visiting the pairs in random order and moving each pair toward its
 * target with a step that shrinks over the epochs; this reaches lower stress than majorisation and does not depend on
 * a good start. Here the target is measured between card borders rather than centres: cards at graph distance d along
 * direction u want r_a(u) + r_b(u) + d·L + (d − 1)·2·r̄(u) between their centres, where r is the distance from a card's
 * centre to its border along u, r̄ the same for a typical card and L the visible length of an arrow. Wide cards then sit
 * side by side at their width plus L and stacked at their height plus L.
 *
 * In the second half of the schedule two hinge terms join in, as in the multicriteria "(SGD)²" of Ahmed et al. (IEEE
 * TVCG 2022): cards closer than their size plus a clearance are pushed apart (FORBID, Giovannangeli et al., GD 2022)
 * and a card cut by a link it is not part of is pushed off the link while the link's ends move the other way (ImPrEd,
 * Simonetto et al., Computer Graphics Forum 2011). A final phase repeats only the hinges until none applies.
 */
import {SpatialGrid} from './spatial-grid.ts';

export type StressProblem = {
  /** Extent of each card from its position: left, right, top and bottom (a card is centred when left = right). */
  left: Float64Array;
  right: Float64Array;
  top: Float64Array;
  bottom: Float64Array;
  /** Positions, read as the start (unless `initialize`) and written with the result. */
  x: Float64Array;
  y: Float64Array;
  /** Links as index pairs [a0, b0, a1, b1, …]; self links and duplicates are ignored. */
  links: Int32Array;
  /** Length of each link in hops (default 1): links at hubs are drawn longer so their neighbourhoods spread out. */
  linkLengths?: Float64Array;
  /** Cards that never move. */
  fixed?: Uint8Array;
  /** Positions to stay near (a previous drawing) and how strongly, relative to a link; 0 = free. */
  anchorX?: Float64Array;
  anchorY?: Float64Array;
  anchorWeight?: Float64Array;
  /** More boxes that move with a card (the cards of its fan), as offsets from its position; only the hinges see them. */
  bodies?: Array<Array<{minX: number; maxX: number; minY: number; maxY: number}> | undefined>;
  /** Lowest allowed coordinates (a half plane beside a fixed hub); −Infinity or absent = none. */
  minX?: Float64Array;
  minY?: Float64Array;
  /** Extra pairs with their own target centre distance and weight factor (similarity springs); not links. */
  springs?: {a: number; b: number; length: number; weight: number}[];
};

export type StressOptions = {
  /** Visible length of an arrow between the borders of two linked cards. */
  edgeLength: number;
  /** Clearance kept between cards side by side and stacked. */
  clearX: number;
  clearY: number;
  /** Clearance kept between a card and a link it is not part of. */
  linkClearance: number;
  epochs: number;
  seed: number;
  /** Start from pivot MDS instead of the given positions. */
  initialize: boolean;
  /** With `initialize`: start from seeded random positions instead (another local minimum to choose from). */
  randomStart: boolean;
  /** Turn the start so its long axis follows the viewport (width / height). */
  aspectRatio?: number;
  overlap: boolean;
  occlusion: boolean;
  /** Weight of a link pair relative to the plain stress weight. */
  linkWeight: number;
  /** Rounds of the hinge-only final phase. */
  settleRounds: number;
  /** Fraction of the step-size schedule to skip: a polish of an existing drawing starts with small steps. */
  startFraction: number;
};

export const DEFAULT_STRESS_OPTIONS: StressOptions = {
  edgeLength: 90, clearX: 48, clearY: 36, linkClearance: 10, epochs: 40, seed: 7, initialize: true, randomStart: false,
  overlap: true, occlusion: true, linkWeight: 1, settleRounds: 40, startFraction: 0,
};


/** Deterministic xorshift generator in [0, 1). */
function random(seed: number) {
  let state = (seed >>> 0) || 0x9e3779b9;
  return () => {
    state ^= state << 13; state >>>= 0;
    state ^= state >>> 17;
    state ^= state << 5; state >>>= 0;
    return state / 4294967296;
  };
}

type Adjacency = {offsets: Int32Array; targets: Int32Array; lengths: Float64Array};

function adjacencyOf(n: number, links: Int32Array, linkLengths?: Float64Array): Adjacency {
  const degree = new Int32Array(n + 1);
  const seen = new Set<number>();
  const kept: number[] = [], keptLengths: number[] = [];
  for (let i = 0; i + 1 < links.length; i += 2) {
    const a = links[i], b = links[i + 1];
    if (a === b || a < 0 || b < 0 || a >= n || b >= n) continue;
    const key = a < b ? a * n + b : b * n + a;
    if (seen.has(key)) continue;
    seen.add(key);
    kept.push(a, b);
    keptLengths.push(Math.max(0.25, linkLengths?.[i >> 1] ?? 1));
    degree[a]++; degree[b]++;
  }
  const offsets = new Int32Array(n + 1);
  for (let i = 0; i < n; i++) offsets[i + 1] = offsets[i] + degree[i];
  const fill = offsets.slice(0, n), targets = new Int32Array(offsets[n]), lengths = new Float64Array(offsets[n]);
  for (let i = 0; i < kept.length; i += 2) {
    const length = keptLengths[i >> 1];
    lengths[fill[kept[i]]] = length; targets[fill[kept[i]]++] = kept[i + 1];
    lengths[fill[kept[i + 1]]] = length; targets[fill[kept[i + 1]]++] = kept[i];
  }
  return {offsets, targets, lengths};
}

/** Shortest-path distances (in hops, links weighted by their lengths) from `source` into `row`; Infinity where none. */
function shortestPaths(adjacency: Adjacency, source: number, row: Float64Array, heap: Int32Array, heapKey: Float64Array, uniform: boolean) {
  row.fill(Infinity);
  row[source] = 0;
  if (uniform) {
    let read = 0, write = 0;
    heap[write++] = source;
    while (read < write) {
      const node = heap[read++], next = row[node] + 1;
      for (let k = adjacency.offsets[node]; k < adjacency.offsets[node + 1]; k++) {
        const other = adjacency.targets[k];
        if (row[other] === Infinity) { row[other] = next; heap[write++] = other; }
      }
    }
    return;
  }
  // Dijkstra with a binary heap of (distance, node); stale entries are skipped.
  let size = 0;
  const push = (node: number, key: number) => {
    let i = size++;
    while (i > 0) { const parent = (i - 1) >> 1; if (heapKey[parent] <= key) break; heap[i] = heap[parent]; heapKey[i] = heapKey[parent]; i = parent; }
    heap[i] = node; heapKey[i] = key;
  };
  push(source, 0);
  while (size) {
    const node = heap[0], key = heapKey[0];
    const lastNode = heap[--size], lastKey = heapKey[size];
    let i = 0;
    while (true) {
      let child = 2 * i + 1;
      if (child >= size) break;
      if (child + 1 < size && heapKey[child + 1] < heapKey[child]) child++;
      if (heapKey[child] >= lastKey) break;
      heap[i] = heap[child]; heapKey[i] = heapKey[child]; i = child;
    }
    if (size) { heap[i] = lastNode; heapKey[i] = lastKey; }
    if (key > row[node]) continue;
    for (let k = adjacency.offsets[node]; k < adjacency.offsets[node + 1]; k++) {
      const other = adjacency.targets[k], candidate = key + adjacency.lengths[k];
      if (candidate < row[other]) { row[other] = candidate; push(other, candidate); }
    }
  }
}

/** Distance from a box's reference point to its border along (ux, uy), for extents left/right/top/bottom. */
function radius(left: number, right: number, top: number, bottom: number, ux: number, uy: number) {
  const ex = ux >= 0 ? right : left, ey = uy >= 0 ? bottom : top;
  const ax = Math.abs(ux), ay = Math.abs(uy);
  if (ax < 1e-9) return ey;
  if (ay < 1e-9) return ex;
  return Math.min(ex / ax, ey / ay);
}

export type StressStats = {epochs: number; pairs: number; overlapsLeft: number; occlusionsLeft: number};

/**
 * Lays out the cards of `problem` (mutating `problem.x` and `problem.y`). Cards in different components only interact
 * through the hinges; callers that want components apart pack them afterwards.
 */
export function stressLayout(problem: StressProblem, overrides: Partial<StressOptions> = {}): StressStats {
  const options = {...DEFAULT_STRESS_OPTIONS, ...overrides};
  const {left, right, top, bottom, x, y} = problem;
  const n = x.length;
  if (!n) return {epochs: 0, pairs: 0, overlapsLeft: 0, occlusionsLeft: 0};
  const fixed = problem.fixed ?? new Uint8Array(n);
  const adjacency = adjacencyOf(n, problem.links, problem.linkLengths);
  const L = options.edgeLength;

  // Typical half extents for the cards a path passes through.
  const halfWidths = Array.from({length: n}, (_, i) => (left[i] + right[i]) / 2).sort((a, b) => a - b);
  const halfHeights = Array.from({length: n}, (_, i) => (top[i] + bottom[i]) / 2).sort((a, b) => a - b);
  const typicalHalfWidth = halfWidths[n >> 1], typicalHalfHeight = halfHeights[n >> 1];

  // All-pairs distances in hops; the callers keep this path to at most a few thousand cards.
  const hops = new Float32Array(n * n), heap = new Int32Array(Math.max(n, adjacency.targets.length + 1)), heapKey = new Float64Array(heap.length);
  const uniform = adjacency.lengths.every(length => length === 1), row = new Float64Array(n);
  for (let i = 0; i < n; i++) { shortestPaths(adjacency, i, row, heap, heapKey, uniform); hops.set(row, i * n); }
  let pairCount = 0, maxHops = 1;
  for (let i = 0; i < n; i++) for (let j = i + 1; j < n; j++) {
    const d = hops[i * n + j];
    if (d !== Infinity) { pairCount++; if (d > maxHops) maxHops = d; }
  }
  const pairA = new Uint32Array(pairCount), pairB = new Uint32Array(pairCount), pairHops = new Float32Array(pairCount);
  for (let i = 0, p = 0; i < n; i++) for (let j = i + 1; j < n; j++) {
    const d = hops[i * n + j];
    if (d !== Infinity) { pairA[p] = i; pairB[p] = j; pairHops[p] = d; p++; }
  }
  const springs = (problem.springs ?? []).filter(s => s.a !== s.b && s.a >= 0 && s.b >= 0 && s.a < n && s.b < n);

  const next = random(options.seed);
  if (options.initialize && options.randomStart) {
    const side = Math.sqrt(n) * (L + typicalHalfWidth + typicalHalfHeight);
    for (let i = 0; i < n; i++) if (!fixed[i]) { x[i] = (next() - 0.5) * side * 1.3; y[i] = (next() - 0.5) * side / 1.3; }
  } else if (options.initialize) initialize(problem, hops, adjacency, typicalHalfWidth, typicalHalfHeight, L, options.aspectRatio ?? 1.6);
  // Coincident cards have no direction to separate along: spread them deterministically.
  separateCoincident(x, y, fixed, next);

  const isoTarget = (d: number) => d * L + (d + 1) * (typicalHalfWidth + typicalHalfHeight);
  const minTarget = L + 2 * Math.min(halfHeights[0], typicalHalfHeight);
  const maxTarget = Math.max(isoTarget(maxHops), minTarget * 2);
  const etaMax = maxTarget * maxTarget, etaMin = 0.02 * minTarget * minTarget;
  const epochs = Math.max(2, options.epochs);
  const decay = Math.log(etaMax / etaMin) / (epochs - 1);
  const order = new Uint32Array(pairCount);
  for (let p = 0; p < pairCount; p++) order[p] = p;
  const anchorWeight = problem.anchorWeight;
  const firstEpoch = Math.min(epochs - 1, Math.floor(epochs * Math.max(0, Math.min(1, options.startFraction))));
  const hingeStart = Math.max(firstEpoch, Math.floor(epochs / 2));

  for (let epoch = firstEpoch; epoch < epochs; epoch++) {
    const eta = etaMax * Math.exp(-decay * epoch);
    // Fisher–Yates shuffle with the seeded generator keeps runs reproducible.
    for (let p = pairCount - 1; p > 0; p--) {
      const q = Math.floor(next() * (p + 1)), t = order[p]; order[p] = order[q]; order[q] = t;
    }
    for (let k = 0; k < pairCount; k++) {
      const p = order[k], a = pairA[p], b = pairB[p];
      if (fixed[a] && fixed[b]) continue;
      const d = pairHops[p];
      let dx = x[a] - x[b], dy = y[a] - y[b];
      let distance = Math.sqrt(dx * dx + dy * dy);
      if (distance < 1e-6) { dx = 1e-3 * (next() - 0.5); dy = 1e-3 * (next() - 0.5); distance = Math.sqrt(dx * dx + dy * dy); }
      const ux = dx / distance, uy = dy / distance;
      const ra = radius(left[a], right[a], top[a], bottom[a], -ux, -uy);
      const rb = radius(left[b], right[b], top[b], bottom[b], ux, uy);
      let target = ra + rb + d * L;
      if (d > 1) target += (d - 1) * 2 * radius(typicalHalfWidth, typicalHalfWidth, typicalHalfHeight, typicalHalfHeight, ux, uy);
      const weight = (d <= 1 ? options.linkWeight : 1) / (target * target);
      movePair(x, y, fixed, a, b, ux, uy, distance, target, Math.min(1, eta * weight));
    }
    for (const spring of springs) {
      const a = spring.a, b = spring.b;
      if (fixed[a] && fixed[b]) continue;
      const dx = x[a] - x[b], dy = y[a] - y[b], distance = Math.max(1e-6, Math.sqrt(dx * dx + dy * dy));
      const weight = spring.weight / (spring.length * spring.length);
      movePair(x, y, fixed, a, b, dx / distance, dy / distance, distance, spring.length, Math.min(1, eta * weight));
    }
    if (anchorWeight) {
      const ax = problem.anchorX!, ay = problem.anchorY!;
      for (let i = 0; i < n; i++) {
        if (fixed[i] || !anchorWeight[i]) continue;
        const mu = Math.min(1, eta * anchorWeight[i] / (minTarget * minTarget));
        x[i] += (ax[i] - x[i]) * mu; y[i] += (ay[i] - y[i]) * mu;
      }
    }
    clamp(problem, fixed);
    if (epoch >= hingeStart) {
      const strength = Math.min(1, (epoch - hingeStart + 1) / Math.max(1, epochs - hingeStart));
      if (options.overlap) overlapHinge(problem, fixed, options, 0.5 * strength);
      if (options.occlusion) occlusionHinge(problem, fixed, adjacency, options, 0.5 * strength);
    }
  }
  let overlapsLeft = 0, occlusionsLeft = 0;
  for (let round = 0; round < options.settleRounds; round++) {
    overlapsLeft = options.overlap ? overlapHinge(problem, fixed, options, 0.6) : 0;
    occlusionsLeft = options.occlusion ? occlusionHinge(problem, fixed, adjacency, options, 0.6) : 0;
    clamp(problem, fixed);
    if (!overlapsLeft && !occlusionsLeft) break;
  }
  return {epochs, pairs: pairCount, overlapsLeft, occlusionsLeft};
}

function clamp(problem: StressProblem, fixed: Uint8Array) {
  const {minX, minY, x, y} = problem;
  if (minX) for (let i = 0; i < x.length; i++) if (!fixed[i] && x[i] < minX[i]) x[i] = minX[i];
  if (minY) for (let i = 0; i < y.length; i++) if (!fixed[i] && y[i] < minY[i]) y[i] = minY[i];
}

/** Moves a pair along its direction (a − b) by `mu` of the way to `target`; a fixed card leaves the whole move to the other. */
function movePair(x: Float64Array, y: Float64Array, fixed: Uint8Array, a: number, b: number, ux: number, uy: number,
  distance: number, target: number, mu: number) {
  const shift = mu * (distance - target) / 2;
  if (fixed[a]) { x[b] += 2 * shift * ux; y[b] += 2 * shift * uy; return; }
  if (fixed[b]) { x[a] -= 2 * shift * ux; y[a] -= 2 * shift * uy; return; }
  x[a] -= shift * ux; y[a] -= shift * uy;
  x[b] += shift * ux; y[b] += shift * uy;
}

function separateCoincident(x: Float64Array, y: Float64Array, fixed: Uint8Array, next: () => number) {
  const seen = new Map<string, number>();
  for (let i = 0; i < x.length; i++) {
    const key = `${Math.round(x[i] * 100)},${Math.round(y[i] * 100)}`;
    const count = seen.get(key) ?? 0;
    seen.set(key, count + 1);
    if (count && !fixed[i]) {
      const angle = count * 2.399963 + next() * 0.1;
      x[i] += Math.cos(angle) * (4 + count);
      y[i] += Math.sin(angle) * (4 + count);
    }
  }
}

/** A box that moves with a card: its own card, or a card of a fan attached to it (offsets from the card's position). */
type Entry = {owner: number; minX: number; maxX: number; minY: number; maxY: number};

function entriesOf(problem: StressProblem): Entry[] {
  const {left, right, top, bottom, bodies} = problem, n = left.length;
  const entries: Entry[] = [];
  for (let i = 0; i < n; i++) {
    entries.push({owner: i, minX: -left[i], maxX: right[i], minY: -top[i], maxY: bottom[i]});
    for (const box of bodies?.[i] ?? []) entries.push({owner: i, ...box});
  }
  return entries;
}

/**
 * Pushes apart boxes of different cards closer than the clearance, along the axis that needs the shorter move (as
 * overlap removal by projection does), by `mu` of the shortfall. Returns how many pairs were too close.
 */
function overlapHinge(problem: StressProblem, fixed: Uint8Array, options: StressOptions, mu: number) {
  const {x, y} = problem;
  const entries = entriesOf(problem);
  const grid = new SpatialGrid(256), found: number[] = [];
  const halfX = options.clearX / 2, halfY = options.clearY / 2;
  for (const e of entries) grid.insert({minX: x[e.owner] + e.minX - halfX, maxX: x[e.owner] + e.maxX + halfX, minY: y[e.owner] + e.minY - halfY, maxY: y[e.owner] + e.maxY + halfY});
  let violations = 0;
  entries.forEach((e, k) => {
    const a = e.owner;
    grid.search(x[a] + e.minX - halfX, y[a] + e.minY - halfY, x[a] + e.maxX + halfX, y[a] + e.maxY + halfY, found);
    for (const l of found) {
      const f = entries[l], b = f.owner;
      if (l <= k || a === b || (fixed[a] && fixed[b])) continue;
      const ax = x[a] + (e.minX + e.maxX) / 2, ay = y[a] + (e.minY + e.maxY) / 2;
      const bx = x[b] + (f.minX + f.maxX) / 2, by = y[b] + (f.minY + f.maxY) / 2;
      const dx = ax - bx, dy = ay - by;
      const needX = (e.maxX - e.minX + f.maxX - f.minX) / 2 + options.clearX;
      const needY = (e.maxY - e.minY + f.maxY - f.minY) / 2 + options.clearY;
      const depthX = needX - Math.abs(dx), depthY = needY - Math.abs(dy);
      if (depthX <= 0.01 || depthY <= 0.01) continue;
      violations++;
      let mx = 0, my = 0;
      if (depthX / Math.max(1, needX) <= depthY / Math.max(1, needY)) mx = (dx >= 0 ? 1 : -1) * depthX;
      else my = (dy >= 0 ? 1 : -1) * depthY;
      if (Math.abs(dx) < 1e-6 && Math.abs(dy) < 1e-6) { mx = needX * (a < b ? 1 : -1); my = 0; }
      const share = fixed[a] ? 0 : fixed[b] ? 1 : 0.5;
      x[a] += mx * mu * share; y[a] += my * mu * share;
      x[b] -= mx * mu * (1 - share); y[b] -= my * mu * (1 - share);
    }
  });
  return violations;
}

/**
 * Pushes cards (and the fans that move with them) off links they are not part of, and the link's ends the other way;
 * returns how many box–link cuts there were.
 */
function occlusionHinge(problem: StressProblem, fixed: Uint8Array, adjacency: Adjacency, options: StressOptions, mu: number) {
  const {x, y} = problem, n = x.length;
  const entries = entriesOf(problem);
  const grid = new SpatialGrid(256), found: number[] = [];
  const pad = options.linkClearance;
  for (const e of entries) grid.insert({minX: x[e.owner] + e.minX - pad, maxX: x[e.owner] + e.maxX + pad, minY: y[e.owner] + e.minY - pad, maxY: y[e.owner] + e.maxY + pad});
  let cuts = 0;
  for (let a = 0; a < n; a++) {
    for (let k = adjacency.offsets[a]; k < adjacency.offsets[a + 1]; k++) {
      const b = adjacency.targets[k];
      if (b < a) continue;
      grid.search(Math.min(x[a], x[b]), Math.min(y[a], y[b]), Math.max(x[a], x[b]), Math.max(y[a], y[b]), found);
      for (const l of found) {
        const e = entries[l], c = e.owner;
        if (c === a || c === b || (fixed[c] && fixed[a] && fixed[b])) continue;
        const minX = x[c] + e.minX - pad, maxX = x[c] + e.maxX + pad, minY = y[c] + e.minY - pad, maxY = y[c] + e.maxY + pad;
        if (!segmentHitsBox(x[a], y[a], x[b], y[b], minX, minY, maxX, maxY)) continue;
        cuts++;
        // Move the box perpendicular to the link, to the side its centre is on, until its extent clears the line.
        const lx = x[b] - x[a], ly = y[b] - y[a], length = Math.max(1e-6, Math.hypot(lx, ly));
        const cx = (minX + maxX) / 2, cy = (minY + maxY) / 2;
        let nx = -ly / length, ny = lx / length;
        let side = (cx - x[a]) * nx + (cy - y[a]) * ny;
        if (Math.abs(side) < 1e-6) side = c % 2 ? 1 : -1;
        if (side < 0) { nx = -nx; ny = -ny; side = -side; }
        const reach = ((maxX - minX) / 2) * Math.abs(nx) + ((maxY - minY) / 2) * Math.abs(ny);
        const shortfall = reach - side;
        if (shortfall <= 0) continue;
        const t = Math.max(0, Math.min(1, ((cx - x[a]) * lx + (cy - y[a]) * ly) / (length * length)));
        const cardShare = fixed[c] ? 0 : fixed[a] && fixed[b] ? 1 : 0.6;
        const move = shortfall * mu;
        x[c] += nx * move * cardShare; y[c] += ny * move * cardShare;
        const linkMove = move * (1 - cardShare);
        if (!fixed[a]) { x[a] -= nx * linkMove * (1 - t); y[a] -= ny * linkMove * (1 - t); }
        if (!fixed[b]) { x[b] -= nx * linkMove * t; y[b] -= ny * linkMove * t; }
      }
    }
  }
  return cuts;
}

/** Whether segment (x0, y0)–(x1, y1) meets the box (Liang–Barsky clipping). */
export function segmentHitsBox(x0: number, y0: number, x1: number, y1: number, minX: number, minY: number, maxX: number, maxY: number) {
  let lo = 0, hi = 1;
  const dx = x1 - x0, dy = y1 - y0;
  for (const [p, q] of [[-dx, x0 - minX], [dx, maxX - x0], [-dy, y0 - minY], [dy, maxY - y0]] as const) {
    if (Math.abs(p) < 1e-12) { if (q < 0) return false; continue; }
    const r = q / p;
    if (p < 0) { if (r > hi) return false; if (r > lo) lo = r; }
    else { if (r < lo) return false; if (r < hi) hi = r; }
  }
  return lo <= hi;
}

/**
 * Pivot MDS (Brandes and Pich, 2006) per component: classical scaling on the distances to up to 64 well-spread pivot
 * cards, turned so the long axis follows the viewport. Fixed cards keep their positions and the rest is shifted to sit
 * around them.
 */
function initialize(problem: StressProblem, hops: Float32Array, adjacency: Adjacency, halfWidth: number, halfHeight: number,
  L: number, aspectRatio: number) {
  const {x, y} = problem, n = x.length;
  const fixed = problem.fixed;
  const component = new Int32Array(n).fill(-1);
  const components: number[][] = [];
  for (let s = 0; s < n; s++) {
    if (component[s] >= 0) continue;
    const members: number[] = [];
    for (let i = 0; i < n; i++) if (hops[s * n + i] !== Infinity) { component[i] = components.length; members.push(i); }
    components.push(members);
  }
  const iso = (d: number) => d * L + d * (halfWidth + halfHeight);
  let offsetX = 0;
  for (const members of components) {
    const m = members.length;
    if (m === 1) { if (!fixed?.[members[0]]) { x[members[0]] = offsetX; y[members[0]] = 0; } offsetX += 4 * halfWidth + L; continue; }
    // Pivots: highest degree first, then each farthest from those chosen.
    const pivotCount = Math.min(m, 64);
    let first = members[0];
    for (const i of members) if (adjacency.offsets[i + 1] - adjacency.offsets[i] > adjacency.offsets[first + 1] - adjacency.offsets[first]) first = i;
    const pivots = [first], nearest = new Float64Array(m).fill(Infinity);
    while (pivots.length < pivotCount) {
      const last = pivots[pivots.length - 1];
      let best = -1, bestDistance = -1;
      members.forEach((i, k) => {
        nearest[k] = Math.min(nearest[k], hops[last * n + i]);
        if (nearest[k] > bestDistance) { bestDistance = nearest[k]; best = i; }
      });
      if (bestDistance <= 0) break;
      pivots.push(best);
    }
    const k = pivots.length;
    // C = −½ J D² J (double-centred squared distances), m × k.
    const C = new Float64Array(m * k), rowMean = new Float64Array(m), colMean = new Float64Array(k);
    let total = 0;
    for (let r = 0; r < m; r++) for (let c = 0; c < k; c++) {
      const value = iso(hops[members[r] * n + pivots[c]]) ** 2;
      C[r * k + c] = value; rowMean[r] += value / k; colMean[c] += value / m; total += value / (m * k);
    }
    for (let r = 0; r < m; r++) for (let c = 0; c < k; c++) C[r * k + c] = -0.5 * (C[r * k + c] - rowMean[r] - colMean[c] + total);
    // Top two eigenvectors of CᵀC by power iteration with deflation; deterministic start vectors.
    const B = new Float64Array(k * k);
    for (let r = 0; r < m; r++) for (let i = 0; i < k; i++) { const ci = C[r * k + i]; if (ci) for (let j = 0; j < k; j++) B[i * k + j] += ci * C[r * k + j]; }
    const vectors: Float64Array[] = [];
    for (let e = 0; e < 2; e++) {
      let v = new Float64Array(k);
      for (let i = 0; i < k; i++) v[i] = e === 0 ? 1 + i / k : (i % 2 ? 1 : -1) * (1 + i / (2 * k));
      for (let iteration = 0; iteration < 200; iteration++) {
        const w = new Float64Array(k);
        for (let i = 0; i < k; i++) { let s = 0; for (let j = 0; j < k; j++) s += B[i * k + j] * v[j]; w[i] = s; }
        for (const u of vectors) { let dot = 0; for (let i = 0; i < k; i++) dot += w[i] * u[i]; for (let i = 0; i < k; i++) w[i] -= dot * u[i]; }
        let norm = 0; for (let i = 0; i < k; i++) norm += w[i] * w[i];
        norm = Math.sqrt(norm);
        if (norm < 1e-12) break;
        let change = 0;
        for (let i = 0; i < k; i++) { const value = w[i] / norm; change += Math.abs(value - v[i]); v[i] = value; }
        v = v.slice();
        if (change < 1e-9) break;
      }
      vectors.push(v);
    }
    const px = new Float64Array(m), py = new Float64Array(m);
    for (let r = 0; r < m; r++) {
      let sx = 0, sy = 0;
      for (let c = 0; c < k; c++) { sx += C[r * k + c] * vectors[0][c]; sy += C[r * k + c] * (vectors[1]?.[c] ?? 0); }
      px[r] = sx; py[r] = sy;
    }
    // Scale so linked cards are about their isotropic target apart.
    const row = new Map(members.map((i, r) => [i, r]));
    let num = 0, den = 0;
    members.forEach((i, r) => {
      for (let q = adjacency.offsets[i]; q < adjacency.offsets[i + 1]; q++) {
        const s = row.get(adjacency.targets[q]);
        if (s === undefined) continue;
        const length = Math.hypot(px[r] - px[s], py[r] - py[s]);
        num += length * iso(1); den += length * length;
      }
    });
    const scale = den > 1e-9 ? num / den : 1;
    // Long axis along the viewport's long axis.
    let mx = 0, my = 0;
    for (let r = 0; r < m; r++) { px[r] *= scale; py[r] *= scale; mx += px[r] / m; my += py[r] / m; }
    let sxx = 0, syy = 0, sxy = 0;
    for (let r = 0; r < m; r++) { const ex = px[r] - mx, ey = py[r] - my; sxx += ex * ex; syy += ey * ey; sxy += ex * ey; }
    const theta = 0.5 * Math.atan2(2 * sxy, sxx - syy) + (aspectRatio < 1 ? Math.PI / 2 : 0);
    const cos = Math.cos(-theta), sin = Math.sin(-theta);
    let minX = Infinity, maxX = -Infinity;
    const placed: Array<[number, number]> = [];
    for (let r = 0; r < m; r++) {
      const ex = px[r] - mx, ey = py[r] - my;
      const rx = ex * cos - ey * sin, ry = ex * sin + ey * cos;
      placed.push([rx, ry]);
      minX = Math.min(minX, rx); maxX = Math.max(maxX, rx);
    }
    // Fixed members pin the component: shift it so their mean sits where they are.
    let shiftX = offsetX - minX, shiftY = 0, fixedCount = 0, fx = 0, fy = 0, px0 = 0, py0 = 0;
    members.forEach((i, r) => { if (fixed?.[i]) { fixedCount++; fx += x[i]; fy += y[i]; px0 += placed[r][0]; py0 += placed[r][1]; } });
    if (fixedCount) { shiftX = (fx - px0) / fixedCount; shiftY = (fy - py0) / fixedCount; }
    members.forEach((i, r) => { if (!fixed?.[i]) { x[i] = placed[r][0] + shiftX; y[i] = placed[r][1] + shiftY; } });
    if (!fixedCount) offsetX += maxX - minX + 4 * halfWidth + L;
  }
}

/**
 * Readability cost of a stress drawing for choosing among starts: link crossings, links cutting a card (counted three
 * times) and overlapping cards (counted twenty times).
 */
export function drawingCost(problem: StressProblem) {
  const {left, right, top, bottom, x, y, links} = problem, n = x.length;
  let crossings = 0, cuts = 0, overlaps = 0;
  const count = links.length / 2;
  for (let p = 0; p < count; p++) {
    const a = links[2 * p], b = links[2 * p + 1];
    for (let q = p + 1; q < count; q++) {
      const c = links[2 * q], d = links[2 * q + 1];
      if (a === c || a === d || b === c || b === d) continue;
      if (segmentsCross(x[a], y[a], x[b], y[b], x[c], y[c], x[d], y[d])) crossings++;
    }
    for (let k = 0; k < n; k++) {
      if (k === a || k === b) continue;
      if (segmentHitsBox(x[a], y[a], x[b], y[b], x[k] - left[k], y[k] - top[k], x[k] + right[k], y[k] + bottom[k])) cuts++;
    }
  }
  for (let i = 0; i < n; i++) for (let j = i + 1; j < n; j++) {
    const dx = x[i] - x[j], dy = y[i] - y[j];
    const needX = dx >= 0 ? left[i] + right[j] : right[i] + left[j], needY = dy >= 0 ? top[i] + bottom[j] : bottom[i] + top[j];
    if (Math.abs(dx) < needX && Math.abs(dy) < needY) overlaps++;
  }
  return crossings + 3 * cuts + 20 * overlaps;
}

function segmentsCross(ax: number, ay: number, bx: number, by: number, cx: number, cy: number, dx: number, dy: number) {
  const d1 = (bx - ax) * (cy - ay) - (by - ay) * (cx - ax), d2 = (bx - ax) * (dy - ay) - (by - ay) * (dx - ax);
  const d3 = (dx - cx) * (ay - cy) - (dy - cy) * (ax - cx), d4 = (dx - cx) * (by - cy) - (dy - cy) * (bx - cx);
  return d1 * d2 < -1e-9 && d3 * d4 < -1e-9;
}

/**
 * Local search over the readability cost (crossings, link cuts, overlaps, as in `drawingCost`): each card involved in
 * a conflict tries nearby positions and the mirror image of its position across the middle of its neighbours, and
 * takes the best that lowers the cost; a small penalty for moving keeps the stress drawing's shape.
 */
export function untangle(problem: StressProblem, passes = 3, {crossings = 1, moveCost = 1 / 12} = {}) {
  const {left, right, top, bottom, x, y, links, bodies} = problem, n = x.length;
  const fixed = problem.fixed ?? new Uint8Array(n);
  const count = links.length / 2;
  const incident: number[][] = Array.from({length: n}, () => []);
  for (let p = 0; p < count; p++) { incident[links[2 * p]].push(p); incident[links[2 * p + 1]].push(p); }
  // Every box that moves with a card: its own, and those of its fan (bodies).
  const own: Array<Array<{minX: number; maxX: number; minY: number; maxY: number}>> = Array.from({length: n}, (_, i) =>
    [{minX: -left[i], maxX: right[i], minY: -top[i], maxY: bottom[i]}, ...(bodies?.[i] ?? [])]);
  const cuts = (ax: number, ay: number, bx: number, by: number, k: number, pad: number) => {
    let hits = 0;
    for (const box of own[k]) if (segmentHitsBox(ax, ay, bx, by, x[k] + box.minX - pad, y[k] + box.minY - pad, x[k] + box.maxX + pad, y[k] + box.maxY + pad)) hits++;
    return hits;
  };
  const linkCost = (p: number) => {
    const a = links[2 * p], b = links[2 * p + 1];
    let cost = 0;
    for (let q = 0; q < count; q++) {
      if (q === p) continue;
      const c = links[2 * q], d = links[2 * q + 1];
      if (a === c || a === d || b === c || b === d) continue;
      if (crossings && segmentsCross(x[a], y[a], x[b], y[b], x[c], y[c], x[d], y[d])) cost += crossings;
    }
    for (let k = 0; k < n; k++) if (k !== a && k !== b) cost += 3 * cuts(x[a], y[a], x[b], y[b], k, 4);
    return cost;
  };
  const cardCost = (i: number) => {
    let cost = 0;
    for (const p of incident[i]) cost += linkCost(p);
    // Links of other cards cutting this card or its fan.
    for (let p = 0; p < count; p++) {
      const a = links[2 * p], b = links[2 * p + 1];
      if (a === i || b === i) continue;
      cost += 3 * cuts(x[a], y[a], x[b], y[b], i, 4);
    }
    for (let k = 0; k < n; k++) {
      if (k === i) continue;
      for (const e of own[i]) for (const f of own[k]) {
        const dx = x[i] + (e.minX + e.maxX) / 2 - x[k] - (f.minX + f.maxX) / 2, dy = y[i] + (e.minY + e.maxY) / 2 - y[k] - (f.minY + f.maxY) / 2;
        if (Math.abs(dx) < (e.maxX - e.minX + f.maxX - f.minX) / 2 + 24 && Math.abs(dy) < (e.maxY - e.minY + f.maxY - f.minY) / 2 + 18) cost += 20;
      }
    }
    return cost;
  };
  // Steps and the cost of moving scale with a typical card, not with the biggest fan.
  const sizes = Array.from({length: n}, (_, i) => (left[i] + right[i] + top[i] + bottom[i]) / 4).sort((a, b) => a - b);
  const scale = Math.max(40, sizes[n >> 1]);
  for (let pass = 0; pass < passes; pass++) {
    let improved = 0;
    for (let i = 0; i < n; i++) {
      if (fixed[i] || !incident[i].length) continue;
      const start = cardCost(i);
      if (!start) continue;
      const x0 = x[i], y0 = y[i];
      const candidates: Array<[number, number]> = [];
      for (const r of [0.6, 1.2, 2, 3.2]) for (let k = 0; k < 8; k++) candidates.push([x0 + Math.cos(k * Math.PI / 4) * r * scale, y0 + Math.sin(k * Math.PI / 4) * r * scale]);
      // A card with one link may swing all the way round the card it hangs from, where it is and at a plain link's
      // distance.
      if (incident[i].length === 1) {
        const o = links[2 * incident[i][0]] === i ? links[2 * incident[i][0] + 1] : links[2 * incident[i][0]];
        const r = Math.hypot(x0 - x[o], y0 - y[o]);
        for (let k = 0; k < 16; k++) {
          const ux = Math.cos(k * Math.PI / 8), uy = Math.sin(k * Math.PI / 8);
          const near = radius(left[o], right[o], top[o], bottom[o], ux, uy) + radius(left[i], right[i], top[i], bottom[i], -ux, -uy) + 90;
          candidates.push([x[o] + ux * r, y[o] + uy * r]);
          if (near < r - 1) candidates.push([x[o] + ux * near, y[o] + uy * near]);
        }
      }
      // Mirror across the neighbours' middle: flips a card to the other side of a crossing.
      let mx = 0, my = 0;
      for (const p of incident[i]) { const o = links[2 * p] === i ? links[2 * p + 1] : links[2 * p]; mx += x[o]; my += y[o]; }
      mx /= incident[i].length; my /= incident[i].length;
      candidates.push([2 * mx - x0, 2 * my - y0]);
      let bestCost = start, bestX = x0, bestY = y0;
      for (const [cx, cy] of candidates) {
        x[i] = cx; y[i] = cy;
        const cost = cardCost(i) + Math.hypot(cx - x0, cy - y0) * moveCost / scale;
        if (cost < bestCost - 0.05) { bestCost = cost; bestX = cx; bestY = cy; }
      }
      x[i] = bestX; y[i] = bestY;
      if (bestX !== x0 || bestY !== y0) { improved++; continue; }
      // Trading places with a nearby card undoes crossings no single move can (two cards on the wrong sides).
      const here = cardCost(i);
      if (!here) continue;
      let bestSwap = -1, bestGain = 0.5;
      for (let j = 0; j < n; j++) {
        if (j === i || fixed[j] || Math.hypot(x[j] - x0, y[j] - y0) > 4 * scale) continue;
        const before = here + cardCost(j);
        x[i] = x[j]; y[i] = y[j]; x[j] = x0; y[j] = y0;
        const gain = before - (cardCost(i) + cardCost(j));
        x[j] = x[i]; y[j] = y[i]; x[i] = x0; y[i] = y0;
        if (gain > bestGain) { bestGain = gain; bestSwap = j; }
      }
      if (bestSwap >= 0) {
        x[i] = x[bestSwap]; y[i] = y[bestSwap]; x[bestSwap] = x0; y[bestSwap] = y0;
        improved++;
      }
    }
    if (!improved) break;
  }
}
